var MERGED_SLOT_HOLDER_MAX_AGE_MS = 24 * 60 * 60 * 1000;

function mergedSlotHolder(owner, name) {
    var merged = parseMcp(github_list_prs({
        workspace: owner, repository: name, state: 'merged'
    }));
    for (var i = 0; i < merged.length; i++) {
