            if (opts.cliThrows) throw new Error(opts.cliThrows);
            return '';
        }
    };
    var bot = loadModule('js/sm/mergeBot.js', makeRequire({}), mods);
    return { bot: bot, calls: calls, mods: mods, wfCalls: wfCalls, crCalls: crCalls, listCalls: listCalls };
}

